"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["32237"],{60950(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.composicao_origem_obrigatoria","status":422,"titulo":"Modalidade com composi\xe7\xe3o RETIRADA_DE_OUTRA_MODALIDADE exige o c\xf3digo de origem"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.composicao_origem_obrigatoria","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada declarou `composicaoVagas: RETIRADA_DE_OUTRA_MODALIDADE` sem\\ndeclarar `composicaoOrigemCodigo`. A composi\xe7\xe3o de vagas \xe9 a dimens\xe3o que\\ndecide como a modalidade entra na aritm\xe9tica do quadro de vagas \u2014 `RETIRADA_DE_OUTRA_MODALIDADE`\\nsignifica que ela n\xe3o tem quadro pr\xf3prio, ela **subtrai** vagas de outra\\nmodalidade selecionada na mesma oferta; sem saber de qual, a subtra\xe7\xe3o n\xe3o\\ntem como ser calculada.","Composi\xe7\xe3o de vagas (`RETIRADA_DE_OUTRA_MODALIDADE`, entre outras) e regra de remanejamento\\n(`DESTINO_UNICO`, `CRUZADO`, entre outras \u2014 ver\\n[`remanejamento_destino_obrigatorio`](/erros/uniplus.selecao.modalidade_selecionada.remanejamento_destino_obrigatorio))\\ns\xe3o duas dimens\xf5es independentes da mesma modalidade: a primeira decide como\\nela entra no c\xe1lculo do quadro; a segunda, o que acontece com as vagas dela\\nque sobram sem candidato aprovado. Este c\xf3digo \xe9 s\xf3 sobre a primeira.","Esta confer\xeancia roda dentro da cria\xe7\xe3o da modalidade, verificando s\xf3 os campos\\ndela mesma \u2014 n\xe3o confere se o c\xf3digo de origem declarado de fato corresponde\\na outra modalidade selecionada nesta oferta (essa \xe9 uma confer\xeancia separada, ver\\n[`configuracao_distribuicao_vagas.composicao_origem_nao_selecionada`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.composicao_origem_nao_selecionada)).\\nEsta recusa sai junto com as demais recusas da modalidade; corrija todas antes de selecionar de novo.","**`composicaoVagas` e `composicaoOrigemCodigo` n\xe3o v\xeam do corpo do pedido da\\ndefini\xe7\xe3o de distribui\xe7\xe3o de vagas** \u2014 s\xe3o copiados do cadastro de\\nmodalidades de Configura\xe7\xe3o, no momento em que a modalidade \xe9 selecionada.\\nNo cadastro, o c\xf3digo de origem \xe9 informado em `composicaoOrigem`.\\nO pr\xf3prio cadastro j\xe1 impede esta incoer\xeancia na\\nescrita, tanto na cria\xe7\xe3o quanto na atualiza\xe7\xe3o; pela defini\xe7\xe3o de\\ndistribui\xe7\xe3o de vagas, este c\xf3digo s\xf3 aparece se a modalidade estiver\\ngravada no cadastro de um jeito que contorna essa valida\xe7\xe3o.","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada modalidade selecionada a partir do que foi\\ncongelado \u2014 a mesma cria\xe7\xe3o \xe9 conferida de novo."],"comoResolver":["O campo que falta n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade\\ncadastrada em Configura\xe7\xe3o. Corrija l\xe1 o v\xednculo entre `composicaoVagas:\\nRETIRADA_DE_OUTRA_MODALIDADE` e o c\xf3digo de origem da modalidade indicada, ou investigue como\\nela foi gravada sem essa coer\xeancia.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema tamb\xe9m n\xe3o est\xe1\\nno que foi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada, que reflete\\numa modalidade j\xe1 incoerente no momento em que foi selecionada."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);